  $sujet${"parties": [{"titre": "الأسئلة", "points": 20, "questions": [{"type": "libre", "numero": "1", "points": 0.5, "enonce": "حدد القضية الأساسية للوضعية.", "correction": "القضية الأساسية للوضعية: (يقبل كل جواب يتعلق بالتخطيط والاستشراف)."}, {"type": "libre", "numero": "2 أ", "points": 0.5, "enonce": "التطلع بأمل و تفاؤل إلى المستقبل من موجبات الإيمان ومقتضيات العلم. أ- حدد دلالة الإيمان بالغيب:", "correction": "أ- أن يحدد دلالة الايمان بالغيب : الانقياد والخضوع المطلق للمشيئة الإلهية (0.5ن)"}, {"type": "libre", "numero": "2 ب", "points": 1, "enonce": "التطلع بأمل و تفاؤل إلى المستقبل من موجبات الإيمان ومقتضيات العلم. ب- استثمر ما ورد في سورة يوسف لتقديم تدبيرين اعتمدهما يوسف عليه السلام في تجاوز الأزمة.", "correction": "ب- أن يقدم تدبيرين اعتمدهما يوسف عليه السلام في تخطي الأزمة: - الإدخار (0.5ن) - التوسط والاعتدال (0.5ن)"}, {"type": "libre", "numero": "3 أ", "points": 0.5, "enonce": "كفايات يوسف عليه السلام مكنته من تقديم حلول ناجعة خلصت البلاد من أزمتها. أ- اذكر أساسين من أسس الكفاءة والاستحقاق.", "correction": "أ- أن يذكر أساسين من أسس الكفاءة والاستحقاق (الأمانة – العلم – العفة...) (0.5ن)"}, {"type": "libre", "numero": "3 ب", "points": 2, "enonce": "كفايات يوسف عليه السلام مكنته من تقديم حلول ناجعة خلصت البلاد من أزمتها. بـ استحضر من سورة يوسف الآيات الدالة على تخطيط يوسف عليه السلام لتخليص البلاد من أزمتها.", "correction": "بـ أن يستحضر من سورة يوسف المقطع الآتي: (2ن) ﴿قَالَ تَزْرَعُونَ سَبْعَ سِنِينَ دَأْباً فَمَا حَصَدتُّمْ فَذَرُوهُ فِے سُنۢبُلِهِۦٓ إِلَّا قَلِيلاً مِّمَّا تَاكُلُونَ ۝٤٧ ثُمَّ يَاتِے مِنۢ بَعْدِ ذَٰلِكَ سَبْعٌ شِدَادٌ يَاكُلْنَ مَا قَدَّمْتُمْ لَهُنَّ إِلَّا قَلِيلاً مِّمَّا تُحْصِنُونَ ۝٤٨ ثُمَّ يَاتِے مِنۢ بَعْدِ ذَٰلِكَ عَامٌ فِيهِ يُغَاثُ اُ۬لنَّاسُ وَفِيهِ يَعْصِرُونَ ۝٤٩﴾"}, {"type": "libre", "numero": "4 أ", "points": 0.5, "enonce": "صلح الحديبية استشراف نبوي لفتح مكة. أ- حدد سياق هذا الصلح.", "correction": "أ- سياق صلح الحديبية: تبشير النبي صلى الله عليه وسلم الصحابة برؤيا دخولهم مكة معتمرين، ومنع القرشيين لهم ودخول الطرفين في تفاوض (0.5ن)"}, {"type": "libre", "numero": "4 ب", "points": 0.5, "enonce": "صلح الحديبية استشراف نبوي لفتح مكة. بـ استحضر بندين من بنوده تظهر فيهما معالم استشراف فتح مكة.", "correction": "بـ أن يستحضر بندين من بنود صلح الحديبية تظهر فيهما معالم استشراف فتح مكة: - وقف القتال لمدة عشر سنوات (0.25ن) - من أحب أن يدخل في حلف محمد صلى الله عليه وسلم وخزاعة دخل، وأنه من أحب أن يدخل في حلف قريش وبني بكر دخل (0.25ن)"}, {"type": "libre", "numero": "5", "points": 1.5, "enonce": "فاوض النبي صلى الله عليه وسلم القرشيين في صلح الحديبية بحكمة ويقين بنصر الله تعالى. أبرز تجليين من تجليات يقين الرسول صلى الله عليه وسلم بنصر الله تعالى.", "correction": "أن يبرز تجليين من تجليات يقين الرسول صلى الله عليه وسلم بنصر الله تعالى: - ثبات النبي صلى الله عليه وسلم على الحق (0.75ن) - قبول شروط الصلح رغم ما ظهر للصحابة من حيف ودنية فيها (0.75ن)"}, {"type": "libre", "numero": "6 أ", "points": 1, "enonce": "مشورة أهل الكفاءة ضروري لتحقيق أمانة الاستخلاف وتعمير الأرض وإصلاحها. أ- ابرز فائدتين من فوائد الشورى في صلاح أحوال الفرد والمجتمع.", "correction": "أ- أن يذكر فائدتين من فوائد الشورى: رص الصف الداخلي وتدبير الاختلاف – تجنب الصراع والعداوات (1ن)"}, {"type": "libre", "numero": "6 ب", "points": 1, "enonce": "مشورة أهل الكفاءة ضروري لتحقيق أمانة الاستخلاف وتعمير الأرض وإصلاحها. بـ أوضح العلاقة بين عفة يوسف عليه السلام وعمارته الأرض.", "correction": "بـ أن يبين أن عمارة يوسف عليه السلام الأرض لم تقم فقط على علمه وكفاءته بل أيضا على عفته (1ن)"}, {"type": "libre", "numero": "7 أ", "points": 0.5, "enonce": "تواجه الأسرة اليوم تحديات عدة للحفاظ على تماسكها وصون حقوق أطفالها. أ- قدم تدبيرين كفيلين بتحصين الأسرة من التفكك.", "correction": "أ- أن يقدم تدبيرين كفيلين بتحصين الأسرة من التفكك: - نشر قيم المودة والرحمة بين أفراد الأسرة (0.25ن) - اعتماد مبدأي التفاوض والتشاور في تدبير شؤونها (0.25ن)"}, {"type": "libre", "numero": "7 ب", "points": 1, "enonce": "تواجه الأسرة اليوم تحديات عدة للحفاظ على تماسكها وصون حقوق أطفالها. بـ كيف نقتدي بنهج يعقوب عليه السلام لرعاية الأطفال في الاسلام.", "correction": "بـ تمثل أخلاق يعقوب عليه السلام في رعاية أبنائه: النصح والإرشاد الدائم، العفو والتسامح، التحلي بالصبر في التعامل معهم، زرع روح الأمل في نفوسهم (1ن)"}, {"type": "libre", "numero": "7 ج", "points": 2, "enonce": "تواجه الأسرة اليوم تحديات عدة للحفاظ على تماسكها وصون حقوق أطفالها. ج- من التحديات التي قد تواجهها الأسرة ما يقع بين أفرادها من عداوة تصل حد المكيدة. استشهد من سورة يوسف على تخطيط إخوة يوسف للتخلص منه وتدبير المكيدة له.", "correction": "ج- أن يستدل من سورة يوسف بالمقطع الآتي: (2ن) ﴿اُقْتُلُواْ يُوسُفَ أَوِ اِطْرَحُوهُ أَرْضاً يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُواْ مِنۢ بَعْدِهِۦ قَوْماً صَٰلِحِينَ ۝٩ قَالَ قَآئِلٌ مِّنْهُمْ لَا تَقْتُلُواْ يُوسُفَ وَأَلْقُوهُ فِے غَيَٰبَٰتِ اِ۬لْجُبِّ يَلْتَقِطْهُ بَعْضُ اُ۬لسَّيَّارَةِ إِن كُنتُمْ فَٰعِلِينَ ۝١٠ قَالُواْ يَٰٓأَبَانَا مَا لَكَ لَا تَامَنَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُۥ لَنَٰصِحُونَ ۝١١ أَرْسِلْهُ مَعَنَا غَداً يَرْتَعِ وَيَلْعَبْ وَإِنَّا لَهُۥ لَحَٰفِظُونَ ۝١٢﴾"}, {"type": "tableau", "numero": "8-1", "points": 1, "enonce": "املأ الجدول الآتي بما يناسب: النازلة: راجع مطلقة بائنة بينونة كبرى قبل انقضاء عدتها", "champs": [{"libelle": "الحكم", "reponse": "حرام (0.5ن)"}, {"libelle": "التعليل", "reponse": "كون المطلقة طلاقا بائنا بينونة كبرى لا تحل له إلا بعد زواجها من آخر زواجا شرعيا (0.5ن)"}]}, {"type": "tableau", "numero": "8-2", "points": 1, "enonce": "املأ الجدول الآتي بما يناسب: النازلة: تحديد قيمة الصداق مع الاتفاق على تأجيل دفعه.", "champs": [{"libelle": "الحكم", "reponse": "مباح (0.5ن)"}, {"libelle": "التعليل", "reponse": "لأن العبرة في تحديده وعدم اسقاطه (0.5ن)"}]}, {"type": "libre", "numero": "9 أ", "points": 2, "enonce": "استثمر السند الأول للإجابة عن الآتي: أ- يستبيح البعض الفواحش ويجاهرون باقترافها بدعوى أن الشباب فترة للاستمتاع بملذات الحياة. انطلق مما تضمنه السند الأول لبيان بطلان هذا التبرير.", "correction": "أ- أن يستثمر ما تضمنه السند الأول ليبين بطلان تبرير استباحة الفواحش كون يوسف عليه السلام وهو الشاب اليافع المغترب الذي دعته ذات جمال ومكانة في قومها للفاحشة تعفف منفقا شبابه في طاعة الله تعالى والدعوة إليه وتسخير علمه وكفاءته في خدمة الصالح العام (2ن)"}, {"type": "tableau", "numero": "9 ب-1", "points": 0.75, "enonce": "استثمر السند الأول للإجابة عن الآتي: بـ استخرج بعد قراءة السند الأول ما تضمنه من قيم وفق الجدول الآتي: القيمة: العدل", "champs": [{"libelle": "المقطع الدال عليها من السند 1", "reponse": "(إِنَّهُۥ لَا يُفْلِحُ اُ۬لظَّٰلِمُونَ) (0.5ن)"}, {"libelle": "أهمية توظيفها في الحياة", "reponse": "احقاق الحق وإشاعة الأمن (0.25ن)"}]}, {"type": "tableau", "numero": "9 ب-2", "points": 0.5, "enonce": "استثمر السند الأول للإجابة عن الآتي: بـ استخرج بعد قراءة السند الأول ما تضمنه من قيم وفق الجدول الآتي: المقطع الدال عليها من السند 1: (ءَاتَيْنَٰهُ حُكْماً وَعِلْماً)", "champs": [{"libelle": "القيمة", "reponse": "الحكمة والعلم. (0.25ن)"}, {"libelle": "أهمية توظيفها في الحياة", "reponse": "تعمير الأرض وتجاوز تحديات المستقبل (0.25ن)"}]}, {"type": "tableau", "numero": "9 ب-3", "points": 0.75, "enonce": "استثمر السند الأول للإجابة عن الآتي: بـ استخرج بعد قراءة السند الأول ما تضمنه من قيم وفق الجدول الآتي: أهمية توظيفها في الحياة: صيانة المجتمع من الفواحش", "champs": [{"libelle": "القيمة", "reponse": "العفة (0.25ن)"}, {"libelle": "المقطع الدال عليها من السند 1", "reponse": "(قَالَ مَعَاذَ اَ۬للَّهِ) (0.5ن)"}]}, {"type": "libre", "numero": "10 أ", "points": 1, "enonce": "في السند الثاني تنصيص على أن عثمان بن عفان رضي الله عنه مضرب المثل في البذل والحياء. أ- أبرز تجليين من تجليات بذله وعطائه رضي الله عنه في سبيل إعزاز الاسلام ونصرته.", "correction": "أ- أن يبرز تجليين من تجليات بذل وعطاء عثمان رضي الله عنه: - إنفاقه في الجهاد في سبيل الله (تجهيزه جيش العسرة في غزوة تبوك) (0.5ن) - إنفاقه في سقي الماء وشراؤه بئر رومة لصالح المسلمين (0.5ن)"}, {"type": "libre", "numero": "10 ب", "points": 0.5, "enonce": "في السند الثاني تنصيص على أن عثمان بن عفان رضي الله عنه مضرب المثل في البذل والحياء. بـ بين أهمية التحلي بخلق الحياء في تحصين الفرد والمجتمع من الفواحش.", "correction": "بـ أن يبين أهمية التحلي بخلق الحياء في تحصين الفرد والمجتمع من الفواحش كونه مانع من الاقتراب منها واتيانها (0.5ن)"}], "texte": "### الوضعية التقويمية:\n\nيعتقد البعض أن استشراف المستقبل والتخطيط له، ضرب من التكهن و التنبؤ، وخوض في عالم الغيب الذي استأثر الله بعلمه ولم يُطْلِعْ عليه أحدا من خلقه، فيما يرى آخرون أن التطلع بأمل و تفاؤل إلى المستقبل تخطيطا وتدبيرا من موجبات الايمان، ومقتضيات العلم، نَهَجَهُ نبي الله يوسف عليه السلام فيما قدمه من حلول، و اقترحه من خطط مستقبلية لتخليص البلاد من أزمتها، و هو ما سار عليه رسول الله صلى الله عليه وسلم في استشرافه فتح مكة الأعظم، إذ وظفه بكفاءة في صلح الحديبية وهو يفاوض المشركين في يقين كامل بنصر الله تعالى وتأييده المؤمنين.\n\nوإذا كان هذا حال الرسل والأنبياء في الأخذ بالأسباب واعتبار مشورة أهل الكفاءة ضروريا لتحقيق أمانة الاستخلاف، وتعمير الأرض وإصلاحها، فحري بنا الاقتداء بمنهجهم في التشاور والتدبير، لتجاوز ما يواجه الأسرة والمجتمع من تحديات تقتضي الحرص على نشر العفو والتسامح بين الناس، وتعزيز قيم المودة والرحمة بين الأزواج، ودعوتهم إلى التعفف والتحلي بالصبر مهما احتدت الخلافات بينهم تفاديا للطلاق وضمانا لرعاية مثلى للأبناء في كنف آبائهم تُحْفَظُ فيها حقوقهم من الضياع، وتَقِيهِمْ شر الفواحش.\n\n### السند1:\n\nقال الله تعالى: ﴿وَلَمَّا بَلَغَ أَشُدَّهُۥٓ ءَاتَيْنَٰهُ حُكْماً وَعِلْماً وَكَذَٰلِكَ نَجْزِے اِ۬لْمُحْسِنِينَ ۝٢٢ وَرَٰوَدَتْهُ اُ۬لتِے هُوَ فِے بَيْتِهَا عَن نَّفْسِهِۦ وَغَلَّقَتِ اِ۬لْأَبْوَٰبَ وَقَالَتْ هِيتَ لَكَ قَالَ مَعَاذَ اَ۬للَّهِ إِنَّهُۥ رَبِّيَ أَحْسَنَ مَثْوَايَ إِنَّهُۥ لَا يُفْلِحُ اُ۬لظَّٰلِمُونَ ۝٢٣ وَلَقَدْ هَمَّتْ بِهِۦ وَهَمَّ بِهَا لَوْلَا أَن رَّءِا بُرْهَٰنَ رَبِّهِۦ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ اُ۬لسُّوٓءَ وَالْفَحْشَآءَ إِنَّهُۥ مِنْ عِبَادِنَا اَ۬لْمُخْلَصِينَ ۝٢٤﴾ سورة يوسف\n\n### السند2:\n\n\"...لقد كان الخليفة عثمان بن عفان رضي الله عنه أُنْمُوذَجاً فذا وتلميذا أمينا في مدرسة الرحمة المهداة وقد بذل أمواله في سبيل الدعوة وسخرها في خدمتها، ولا شك فهو من كان يستحي منه الرحمة المهداة لأن ملائكة السماء تستحي منه...\"\n\n*تاريخ المبرزين من فقهاء الصحابة، د قحطان حمدي محمد، ص 111/110*", "consigne": "إقرأ الوضعية و الأسناد المصاحبة، ثم أجب عن الأسئلة المرافقة:"}]}$sujet$::jsonb
)
